function tokenize(expr) {
  const tokens = [];
  let i = 0;
  while (i < expr.length) {
    const ch = expr[i];
    if (ch === " ") {
      i += 1;
      continue;
    }
    if (ch === "+" || ch === "-" || ch === "*" || ch === "/" || ch === "(" || ch === ")") {
      tokens.push(ch);
      i += 1;
      continue;
    }
    if (ch >= "0" && ch <= "9") {
      let digits = "";
      while (i < expr.length && expr[i] >= "0" && expr[i] <= "9") {
        digits += expr[i];
        i += 1;
      }
      tokens.push(Number(digits));
      continue;
    }
    throw new Error(`Unexpected character in expression: ${JSON.stringify(ch)}`);
  }
  return tokens;
}

export function calc(expr) {
  const tokens = tokenize(expr);
  let pos = 0;

  const peek = () => tokens[pos];
  const advance = () => tokens[pos++];

  function parseExpr() {
    let value = parseTerm();
    while (peek() === "+" || peek() === "-") {
      const op = advance();
      const rhs = parseTerm();
      value = op === "+" ? value + rhs : value - rhs;
    }
    return value;
  }

  function parseTerm() {
    let value = parseFactor();
    while (peek() === "*" || peek() === "/") {
      const op = advance();
      const rhs = parseFactor();
      value = op === "*" ? value * rhs : value / rhs;
    }
    return value;
  }

  function parseFactor() {
    const token = peek();
    if (token === undefined) {
      throw new Error("Unexpected end of expression");
    }
    if (token === "-") {
      advance();
      return -parseFactor();
    }
    if (token === "(") {
      advance();
      const value = parseExpr();
      if (advance() !== ")") {
        throw new Error("Missing closing parenthesis");
      }
      return value;
    }
    if (typeof token === "number") {
      return advance();
    }
    throw new Error(`Unexpected token: ${JSON.stringify(token)}`);
  }

  const result = parseExpr();
  if (pos !== tokens.length) {
    throw new Error("Unexpected trailing input");
  }
  return result;
}

import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import path from "node:path";
import { calc } from "../lib/calc.mjs";

test("arithmetic", () => {
  assert.equal(calc("2+3*4"), 14);
});

test("spaces are ignored", () => {
  assert.equal(calc(" 2 + 3 * 4 "), 14);
});

test("parentheses override precedence", () => {
  assert.equal(calc("(2+3)*4"), 20);
  assert.equal(calc("2*(3+(4-1))"), 12);
});

test("subtraction is left-associative", () => {
  assert.equal(calc("10-4-3"), 3);
});

test("division returns the true quotient", () => {
  assert.equal(calc("7/2"), 3.5);
});

test("unary minus is supported", () => {
  assert.equal(calc("-(2+3)*4"), -20);
});

test("invalid input throws", () => {
  assert.throws(() => calc("2+"));
  assert.throws(() => calc("foo"));
  assert.throws(() => calc("(2+3"));
  assert.throws(() => calc("2 3"));
});

test("implementation contains no dynamic code execution APIs", () => {
  const calcPath = path.join(
    path.dirname(fileURLToPath(import.meta.url)),
    "../lib/calc.mjs"
  );
  const source = readFileSync(calcPath, "utf8");
  assert.ok(!source.includes("eval"));
  assert.ok(!source.includes("Function"));
});
